    static let ANTENNAS: VOffset = 4
    static let TRANSMITTERS: VOffset = 6
    static let RECEIVERS: VOffset = 8
    static let TRANSPONDERS: VOffset = 10
    static let INSTALLATIONS: VOffset = 12
    static let TRACE_ID: VOffset = 14
    static let ATTESTATION: VOffset = 16
  }

  public var ANTENNAS: FlatbufferVector<TRHAntenna> { return _accessor.vector(at: VT.ANTENNAS, byteSize: 4) }
  public var TRANSMITTERS: FlatbufferVector<TRHTransmitter> { return _accessor.vector(at: VT.TRANSMITTERS, byteSize: 4) }
  public var RECEIVERS: FlatbufferVector<TRHReceiver> { return _accessor.vector(at: VT.RECEIVERS, byteSize: 4) }
  public var TRANSPONDERS: FlatbufferVector<TRHTransponder> { return _accessor.vector(at: VT.TRANSPONDERS, byteSize: 4) }
  public var INSTALLATIONS: FlatbufferVector<TRHInstallation> { return _accessor.vector(at: VT.INSTALLATIONS, byteSize: 4) }
  public var TRACE_ID: String? { let o = _accessor.offset(VT.TRACE_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var TRACE_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.TRACE_ID) }
  public var ATTESTATION: TRHAttestation? { let o = _accessor.offset(VT.ATTESTATION); return o == 0 ? nil : TRHAttestation(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public static func startTRH(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 7) }
  public static func addVectorOf(ANTENNAS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ANTENNAS, at: VT.ANTENNAS) }
  public static func addVectorOf(TRANSMITTERS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: TRANSMITTERS, at: VT.TRANSMITTERS) }
  public static func addVectorOf(RECEIVERS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RECEIVERS, at: VT.RECEIVERS) }
  public static func addVectorOf(TRANSPONDERS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: TRANSPONDERS, at: VT.TRANSPONDERS) }
  public static func addVectorOf(INSTALLATIONS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: INSTALLATIONS, at: VT.INSTALLATIONS) }
  public static func add(TRACE_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: TRACE_ID, at: VT.TRACE_ID) }
  public static func add(ATTESTATION: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ATTESTATION, at: VT.ATTESTATION) }
  public static func endTRH(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
